        .replace(/&amp;/g, '&');   // Fix ampersands
}

return {
    jobDescription: jobDescription.trim()
};

const raw = $input.item.json.data || ""; 

return { 
    jobDescription: raw.split("Markdown Content:")[1]?.trim() || raw 
};

const rawData = $input.item.json.data;

const startMarker = '"description":"';
const endMarker = '","directApply"';

let jobDescription = "";

if (rawData.includes(startMarker) && rawData.includes(endMarker)) {
    jobDescription = rawData.split(startMarker)[1].split(endMarker)[0];

    jobDescription = jobDescription
        .replace(/\\n/g, ' ')        // Remove newlines
        .replace(/\\"/g, '"')        // Fix escaped quotes
        .replace(/<[^>]*>/g, ' ')    // Remove all HTML tags (<p>, <strong>, etc.)
        .replace(/&nbsp;/g, ' ')     // Fix spaces
        .replace(/&amp;/g, '&')      // Fix ampersands
        .replace(/\s+/g, ' ')        // Collapse extra white space
        .trim();
}

return {
    jobDescription: jobDescription
};

const html = $input.item.json.data || "";
const leverRegex = /<div[^>]*data-qa="job-description"[^>]*>([\s\S]*?)<div[^>]*data-qa="btn-apply-bottom"/i;
let match = html.match(leverRegex);

if (match && match[1]) {
    let cleanText = match[1];

    // Remove HTML tags, replacing them with newlines for block elements
    cleanText = cleanText.replace(/<(div|p|li|h3|h2)[^>]*>/gi, "\n");
    cleanText = cleanText.replace(/<[^>]*>/g, "");

    // Clean up escaped HTML entities
    cleanText = cleanText.replace(/&nbsp;/g, " ")
                         .replace(/&amp;/g, "&")
                         .replace(/&lt;/g, "<")
                         .replace(/&gt;/g, ">");

    // Remove excessive whitespace
    cleanText = cleanText.replace(/\n\s*\n/g, "\n\n").trim();

    return { jobDescription: cleanText };
}

const platformName = "aijobsnet";

for (const item of $input.all()) {
  item.json.source = platformName;
}

return $input.all();

const processedItems = [];

for (const item of items) {
    const htmlInput = item.json.data || ""; 
    const headersInput = item.json.headers || {};

    // Micro-function 1: Extract the apply URL path and strip out the ID hash
    const applyPathRegex = /href="(\/job\/([a-zA-Z0-9]+)\/apply\/)"/;
    const match = htmlInput.match(applyPathRegex);
    let finalUrl = "";
    let jobId = "";

    if (match) {
        if (match[1]) {
            const baseUrl = "https://aijobs.net";
            finalUrl = `${baseUrl}${match[1]}`;
        }
        if (match[2]) {
            jobId = match[2];
        }
    }

    // Micro-function 2: Extract and structure the set-cookie data
    let cookieHeader = headersInput["set-cookie"] || "";
    let extractedCookie = "";

    if (Array.isArray(cookieHeader)) {
        extractedCookie = cookieHeader.join("; ");
    } else if (typeof cookieHeader === "string") {
        extractedCookie = cookieHeader;
    }

    // Micro-function 3: Extract the raw CSRF token value alone
    let csrfTokenOnly = "";
    const tokenMatch = extractedCookie.match(/csrftoken=([^;]+)/);

    if (tokenMatch && tokenMatch[1]) {
        csrfTokenOnly = tokenMatch[1];
    }

    // Micro-function 4: Reconstruct Company Name from the structural URL link slug
    let companyName = "";
    const companySlugMatch = htmlInput.match(/href="\/company\/([a-zA-Z0-9-]+)-\d+\/"/i);
    if (companySlugMatch && companySlugMatch[1]) {
        companyName = companySlugMatch[1]
            .split("-")
            .map(word => word.charAt(0).toUpperCase() + word.slice(1))
            .join(" ");
    }

    // Micro-function 5: Pull Location from the HTML header Title Tag
    let location = "";
    const titleLocationMatch = htmlInput.match(/<title>[^<-]+-\s*([^<]+)<\/title>/i);
    if (titleLocationMatch && titleLocationMatch[1]) {
        location = titleLocationMatch[1].trim();
    }

    // Micro-function 6: Parse relative time string and calculate an ISO absolute timestamp
    let publishedAtIso = null;
    const publishedMatch = htmlInput.match(/Found\s+([a-zA-Z0-9\s]+?)(?=\s*(?:\n|<))/i);

    if (publishedMatch && publishedMatch[1]) {
        const relativeStr = publishedMatch[1].trim().toLowerCase(); // e.g., "15h ago", "1d ago", "2mo ago"
        const timeValueMatch = relativeStr.match(/^(\d+)\s*([a-z]+)/);

        if (timeValueMatch) {
            const amount = parseInt(timeValueMatch[1], 10);
            const unit = timeValueMatch[2];
            const dateObj = new Date();

            if (unit.startsWith("h")) {
                dateObj.setHours(dateObj.getHours() - amount);
            } else if (unit.startsWith("d")) {
                dateObj.setDate(dateObj.getDate() - amount);
            } else if (unit.startsWith("m")) {
                dateObj.setMonth(dateObj.getMonth() - amount);
            }

            publishedAtIso = dateObj.toISOString();
        }
    }

    // Fallback to current system execution time if extraction fails entirely
    if (!publishedAtIso) {
        publishedAtIso = new Date().toISOString();
    }

    processedItems.push({
        json: {
            id: jobId || null,
            companyName: companyName || null,
            location: location || null,
            publishedAt: publishedAtIso || null,
            applyUrl: finalUrl || null,
            sessionCookie: extractedCookie || null,
            csrfToken: csrfTokenOnly || null
        }
    });
}

return processedItems;

